const item = $input.first().json;
const body = item.body && typeof item.body === 'object' ? item.body : item;
const headers = item.headers || {};
const key = String(headers['x-arca-key'] || headers['X-Arca-Key'] || '');
const expected = String($env.ARCA_ROBOT_KEY || '');
if (!expected || key !== expected) throw new Error('NO_AUTORIZADO');
const modo = String(body.modo || '');
if (modo === 'anular' || modo === 'explorar') {
  if (modo === 'anular' && !body.envioId) throw new Error('FALTA_ENVIO');
  return [{ json: { modo, envioId: String(body.envioId || ''), empresaId: String(body.empresaId || '') } }];
}
if (!body.loteId || !body.archivo) throw new Error('FALTA_LOTE');
return [{ json: { modo: 'subir', archivo: String(body.archivo), loteId: String(body.loteId), cuit: String(body.cuit || ''), tipo: String(body.tipo || 'AT'), empresaId: String(body.empresaId || ''), canal: String(body.canal || '') } }];
